define(['core/ajax', 'core/notification', 'core/str', 'core/form-autocomplete'], function(Ajax, Notification, Str, Autocomplete) {

    var SELECTORS = {
        FILTER_TYPE: '#lpp-export-filtertype',
        SESSION: '#lpp-export-session',
        COURSE: '#lpp-export-course',
        COHORT: '#lpp-export-cohort',
        TARGET: '.lpp-export-target',
        ROLESET: '#lpp-export-roleset',
        ROLE_FILTER: '[data-role-filter]',
        FILENAME_STRATEGY: '#lpp-export-filenamestrategy',
        EXPORT_TYPE: '#lpp-export-type',
        DENSITY: '#lpp-export-density',
        LANGUAGE: '#lpp-export-language',
        STAGE: '#lpp-export-stage',
        HEADING: '#lpp-export-heading',
        SECTION_DOCUMENT: '[data-section="document"]',
        SECTION_ZIP: '[data-section="zip"]',
        GENERATE_BTN: '#lpp-export-btn',
        STATUS: '#lpp-export-status',
        MODE_STANDARD: '[data-mode="standard"]',
        MODE_ACTIVITY: '[data-mode="activity"]',
        ACTIVITY_COHORT: '#lpp-activity-cohort',
        ACTIVITY_COHORT_INFO: '#lpp-activity-cohort-info',
        ACTIVITY_NAME: '#lpp-activity-name',
        ACTIVITY_DATE: '#lpp-activity-date',
        ACTIVITY_PLACE: '#lpp-activity-place',
        ACTIVITY_RESPONSABLES: '#lpp-activity-responsables',
        ACTIVITY_TEMPLATE: '#lpp-activity-template',
        ACTIVITY_COLUMNS_GRID: '#lpp-activity-columns-grid',
        ACTIVITY_CUSTOMCOLUMNS: '#lpp-activity-customcolumns',
        ACTIVITY_ADDCOLUMN_BTN: '#lpp-activity-addcolumn-btn',
        ACTIVITY_COLUMNS_WARNING: '#lpp-activity-columns-warning',
        ACTIVITY_ORDER_LIST: '#lpp-activity-order-list',
        ACTIVITY_SHOWPHOTOS: '#lpp-activity-showphotos',
        ACTIVITY_SHOWGENERALOBS: '#lpp-activity-showgeneralobs',
        ACTIVITY_ORDER: '#lpp-activity-order',
        ACTIVITY_DENSITY: '#lpp-activity-density',
        ACTIVITY_STAGE: '#lpp-activity-stage',
        ACTIVITY_LANGUAGE: '#lpp-activity-language',
        ACTIVITY_PREVIEW_BTN: '#lpp-activity-preview-btn',
        ACTIVITY_GENERATE_BTN: '#lpp-activity-generate-btn',
        ACTIVITY_PREVIEW_FRAME: '#lpp-activity-preview-frame',
        ACTIVITY_PREVIEW_PLACEHOLDER: '#lpp-activity-preview-placeholder',
        EXPORT_ROOT: '.local-profilephoto-export',
    };

    var WIDE_CLASS = 'lpp-export--wide';

    var MAX_EXTRA_COLUMNS = 6;
    var MAX_CUSTOM_COLUMNS = 4;

    var COLUMN_TEMPLATES = {
        sortida: ['present', 'autoritzacio', 'transport', 'menu', 'observacions'],
        activitat: ['present', 'material', 'observacions'],
        taller: ['present', 'epi', 'grupequip', 'material', 'observacions'],
    };

    var getExportOptions = function() {
        return Ajax.call([{
            methodname: 'local_profilephoto_get_export_options',
            args: {},
        }])[0];
    };

    var createExport = function(filtertype, filterid, filenamestrategy, exporttype, language, stage, heading, density, roleset) {
        return Ajax.call([{
            methodname: 'local_profilephoto_create_export',
            args: {filtertype: filtertype, filterid: filterid, filenamestrategy: filenamestrategy, fallbackstrategy: 'username', exporttype: exporttype, language: language, stage: stage, heading: heading, density: density, roleset: roleset},
        }])[0];
    };

    var getActivityCohorts = function() {
        return Ajax.call([{
            methodname: 'local_profilephoto_get_activity_cohorts',
            args: {},
        }])[0];
    };

    var getActivityCohortInfo = function(cohortid) {
        return Ajax.call([{
            methodname: 'local_profilephoto_get_activity_cohort_info',
            args: {cohortid: cohortid},
        }])[0];
    };

    var createActivityExport = function(args) {
        return Ajax.call([{
            methodname: 'local_profilephoto_create_activity_export',
            args: args,
        }])[0];
    };

    var populateSelect = function(selectEl, options, labelFn) {
        selectEl.innerHTML = '';
        options.forEach(function(option) {
            var optionEl = document.createElement('option');
            optionEl.value = option.id;
            optionEl.textContent = labelFn(option);
            selectEl.appendChild(optionEl);
        });
    };

    var makeSearchable = function(selector) {
        return Str.getString('export_search', 'local_profilephoto').then(function(placeholder) {
            return Str.getString('export_target_none', 'local_profilephoto').then(function(noSelection) {
                return Autocomplete.enhance(selector, false, '', placeholder, false, true, noSelection, true);
            });
        }).catch(Notification.exception);
    };

    var initStandardMode = function() {
        var filterType = document.querySelector(SELECTORS.FILTER_TYPE);
        var sessionSelect = document.querySelector(SELECTORS.SESSION);
        var courseSelect = document.querySelector(SELECTORS.COURSE);
        var cohortSelect = document.querySelector(SELECTORS.COHORT);
        var targets = document.querySelectorAll(SELECTORS.TARGET);
        var roleset = document.querySelector(SELECTORS.ROLESET);
        var roleFilter = document.querySelector(SELECTORS.ROLE_FILTER);
        var filenameStrategy = document.querySelector(SELECTORS.FILENAME_STRATEGY);
        var exportType = document.querySelector(SELECTORS.EXPORT_TYPE);
        var density = document.querySelector(SELECTORS.DENSITY);
        var language = document.querySelector(SELECTORS.LANGUAGE);
        var stage = document.querySelector(SELECTORS.STAGE);
        var heading = document.querySelector(SELECTORS.HEADING);
        var documentSections = document.querySelectorAll(SELECTORS.SECTION_DOCUMENT);
        var zipSections = document.querySelectorAll(SELECTORS.SECTION_ZIP);
        var generateBtn = document.querySelector(SELECTORS.GENERATE_BTN);
        var status = document.querySelector(SELECTORS.STATUS);

        var updateFilterVisibility = function() {
            targets.forEach(function(target) {
                target.hidden = target.dataset.target !== filterType.value;
            });
            if (roleFilter) {
                roleFilter.hidden = filterType.value !== 'course';
            }
        };

        var updateSectionVisibility = function() {
            var isZip = exportType.value === 'zip';
            documentSections.forEach(function(el) {
                el.hidden = isZip;
            });
            zipSections.forEach(function(el) {
                el.hidden = !isZip;
            });
        };

        filterType.addEventListener('change', updateFilterVisibility);
        exportType.addEventListener('change', updateSectionVisibility);
        updateFilterVisibility();
        updateSectionVisibility();

        getExportOptions().then(function(options) {
            populateSelect(sessionSelect, options.sessions, function(s) {
                return s.label;
            });
            populateSelect(courseSelect, options.courses, function(c) {
                return c.name;
            });
            populateSelect(cohortSelect, options.cohorts, function(c) {
                return c.name;
            });
            return Promise.all([
                makeSearchable(SELECTORS.COHORT),
                makeSearchable(SELECTORS.COURSE),
            ]);
        }).catch(Notification.exception);

        generateBtn.addEventListener('click', function() {
            var filtertype = filterType.value;
            var select = filtertype === 'session' ? sessionSelect : (filtertype === 'course' ? courseSelect : cohortSelect);
            var filterid = parseInt(select.value, 10);

            if (!filterid) {
                return;
            }

            generateBtn.disabled = true;
            Str.getString('export_generating', 'local_profilephoto').then(function(message) {
                status.textContent = message;
                return createExport(filtertype, filterid, filenameStrategy.value, exportType.value, language.value, stage.value, (heading.value || '').trim(), density.value, roleset.value);
            }).then(function(result) {
                return Str.getString('export_ready', 'local_profilephoto', result.count).then(function(message) {
                    status.textContent = message;
                    window.location.href = M.cfg.wwwroot + '/local/profilephoto/export.php?token=' + result.token;
                    return null;
                });
            }).catch(Notification.exception).finally(function() {
                generateBtn.disabled = false;
            });
        });
    };

    var initModeToggle = function() {
        var exportType = document.querySelector(SELECTORS.EXPORT_TYPE);
        var standardBlocks = document.querySelectorAll(SELECTORS.MODE_STANDARD);
        var activityBlocks = document.querySelectorAll(SELECTORS.MODE_ACTIVITY);
        var root = document.querySelector(SELECTORS.EXPORT_ROOT);

        var update = function() {
            var isActivity = exportType.value === 'activity';
            standardBlocks.forEach(function(el) {
                el.hidden = isActivity;
            });
            activityBlocks.forEach(function(el) {
                el.hidden = !isActivity;
            });
            if (root) {
                root.classList.toggle(WIDE_CLASS, isActivity);
            }
        };

        exportType.addEventListener('change', update);
        update();
    };

    var initActivityMode = function() {
        var cohortSelect = document.querySelector(SELECTORS.ACTIVITY_COHORT);
        var cohortInfo = document.querySelector(SELECTORS.ACTIVITY_COHORT_INFO);
        var template = document.querySelector(SELECTORS.ACTIVITY_TEMPLATE);
        var columnsGrid = document.querySelector(SELECTORS.ACTIVITY_COLUMNS_GRID);
        var customColumnsEl = document.querySelector(SELECTORS.ACTIVITY_CUSTOMCOLUMNS);
        var addColumnBtn = document.querySelector(SELECTORS.ACTIVITY_ADDCOLUMN_BTN);
        var columnsWarning = document.querySelector(SELECTORS.ACTIVITY_COLUMNS_WARNING);
        var orderList = document.querySelector(SELECTORS.ACTIVITY_ORDER_LIST);
        var previewBtn = document.querySelector(SELECTORS.ACTIVITY_PREVIEW_BTN);
        var generateBtn = document.querySelector(SELECTORS.ACTIVITY_GENERATE_BTN);
        var previewFrame = document.querySelector(SELECTORS.ACTIVITY_PREVIEW_FRAME);
        var previewPlaceholder = document.querySelector(SELECTORS.ACTIVITY_PREVIEW_PLACEHOLDER);
        var status = document.querySelector(SELECTORS.STATUS);

        var state = {
            orderedKeys: [],
            customMeta: {},
            customCounter: 0,
        };

        var standardCheckboxes = function() {
            return Array.prototype.slice.call(columnsGrid.querySelectorAll('input[type="checkbox"]'));
        };

        var standardLabel = function(key) {
            var checkbox = columnsGrid.querySelector('[data-col-key="' + key + '"]');
            return checkbox ? checkbox.closest('label').textContent.trim() : key;
        };

        var columnType = function(key) {
            if (state.customMeta[key]) {
                return state.customMeta[key].type;
            }
            var checkbox = columnsGrid.querySelector('[data-col-key="' + key + '"]');
            return checkbox ? checkbox.dataset.colType : 'checkbox';
        };

        var columnLabel = function(key) {
            return state.customMeta[key] ? (state.customMeta[key].label || '') : standardLabel(key);
        };

        var moveColumn; // Forward-declared: referenced by renderOrderList, defined below.
        var removeCustomColumn; // Forward-declared: referenced by applyTemplate, defined below.

        var enforceColumnLimit = function() {
            var atLimit = state.orderedKeys.length >= MAX_EXTRA_COLUMNS;
            columnsWarning.hidden = state.orderedKeys.length <= MAX_EXTRA_COLUMNS;
            standardCheckboxes().forEach(function(checkbox) {
                if (!checkbox.checked) {
                    checkbox.disabled = atLimit;
                }
            });
            addColumnBtn.disabled = atLimit || Object.keys(state.customMeta).length >= MAX_CUSTOM_COLUMNS;
        };

        var renderOrderList = function() {
            orderList.innerHTML = '';
            state.orderedKeys.forEach(function(key, index) {
                var li = document.createElement('li');
                li.className = 'lpp-activity-order-item';

                var label = document.createElement('span');
                label.className = 'lpp-activity-order-label';
                label.textContent = columnLabel(key) || key;
                li.appendChild(label);

                var controls = document.createElement('span');
                controls.className = 'lpp-activity-order-controls';

                var upBtn = document.createElement('button');
                upBtn.type = 'button';
                upBtn.className = 'btn btn-sm btn-link';
                upBtn.textContent = '↑';
                upBtn.disabled = index === 0;
                upBtn.addEventListener('click', function() {
                    moveColumn(key, -1);
                });
                controls.appendChild(upBtn);

                var downBtn = document.createElement('button');
                downBtn.type = 'button';
                downBtn.className = 'btn btn-sm btn-link';
                downBtn.textContent = '↓';
                downBtn.disabled = index === state.orderedKeys.length - 1;
                downBtn.addEventListener('click', function() {
                    moveColumn(key, 1);
                });
                controls.appendChild(downBtn);

                li.appendChild(controls);
                orderList.appendChild(li);
            });
        };

        moveColumn = function(key, delta) {
            var index = state.orderedKeys.indexOf(key);
            var target = index + delta;
            if (index === -1 || target < 0 || target >= state.orderedKeys.length) {
                return;
            }
            var tmp = state.orderedKeys[index];
            state.orderedKeys[index] = state.orderedKeys[target];
            state.orderedKeys[target] = tmp;
            renderOrderList();
        };

        var syncFromCheckboxes = function() {
            standardCheckboxes().forEach(function(checkbox) {
                var key = checkbox.dataset.colKey;
                var present = state.orderedKeys.indexOf(key) !== -1;
                if (checkbox.checked && !present) {
                    state.orderedKeys.push(key);
                } else if (!checkbox.checked && present) {
                    state.orderedKeys = state.orderedKeys.filter(function(k) {
                        return k !== key;
                    });
                }
            });
            enforceColumnLimit();
            renderOrderList();
        };

        var renderCustomColumnRow = function(key) {
            Str.getString('activity_customcolumn_name', 'local_profilephoto').then(function(nameLabel) {
                var row = document.createElement('div');
                row.className = 'lpp-activity-customcolumn-row';
                row.dataset.key = key;

                var nameInput = document.createElement('input');
                nameInput.type = 'text';
                nameInput.className = 'form-control';
                nameInput.setAttribute('aria-label', nameLabel);
                nameInput.maxLength = 40;
                nameInput.addEventListener('input', function() {
                    state.customMeta[key].label = nameInput.value.trim();
                    renderOrderList();
                });

                var typeSelect = document.createElement('select');
                typeSelect.className = 'form-control';
                return Promise.all([
                    Str.getString('activity_customcolumn_type_checkbox', 'local_profilephoto'),
                    Str.getString('activity_customcolumn_type_text', 'local_profilephoto'),
                    Str.getString('activity_customcolumn_remove', 'local_profilephoto'),
                    Str.getString('activity_customcolumn_placeholder', 'local_profilephoto'),
                ]).then(function(results) {
                    var checkboxLabel = results[0];
                    var textLabel = results[1];
                    var removeLabel = results[2];
                    var placeholder = results[3];

                    nameInput.placeholder = placeholder;

                    var checkboxOption = document.createElement('option');
                    checkboxOption.value = 'checkbox';
                    checkboxOption.textContent = checkboxLabel;
                    typeSelect.appendChild(checkboxOption);

                    var textOption = document.createElement('option');
                    textOption.value = 'text';
                    textOption.textContent = textLabel;
                    typeSelect.appendChild(textOption);

                    typeSelect.addEventListener('change', function() {
                        state.customMeta[key].type = typeSelect.value;
                    });

                    var removeBtn = document.createElement('button');
                    removeBtn.type = 'button';
                    removeBtn.className = 'btn btn-sm btn-link lpp-activity-customcolumn-remove';
                    removeBtn.textContent = '✕';
                    removeBtn.setAttribute('aria-label', removeLabel);
                    removeBtn.addEventListener('click', function() {
                        removeCustomColumn(key);
                    });

                    row.appendChild(nameInput);
                    row.appendChild(typeSelect);
                    row.appendChild(removeBtn);
                    customColumnsEl.appendChild(row);
                    return null;
                });
            }).catch(Notification.exception);
        };

        var addCustomColumn = function() {
            if (state.orderedKeys.length >= MAX_EXTRA_COLUMNS
                    || Object.keys(state.customMeta).length >= MAX_CUSTOM_COLUMNS) {
                enforceColumnLimit();
                return;
            }
            state.customCounter++;
            var key = 'custom' + state.customCounter;
            state.customMeta[key] = {label: '', type: 'checkbox'};
            state.orderedKeys.push(key);
            renderCustomColumnRow(key);
            enforceColumnLimit();
            renderOrderList();
        };

        removeCustomColumn = function(key) {
            delete state.customMeta[key];
            state.orderedKeys = state.orderedKeys.filter(function(k) {
                return k !== key;
            });
            var row = customColumnsEl.querySelector('[data-key="' + key + '"]');
            if (row) {
                row.remove();
            }
            enforceColumnLimit();
            renderOrderList();
        };

        var applyTemplate = function(name) {
            if (name === 'personalitzat' || !COLUMN_TEMPLATES[name]) {
                return;
            }
            Object.keys(state.customMeta).forEach(function(key) {
                removeCustomColumn(key);
            });

            var keys = COLUMN_TEMPLATES[name];
            standardCheckboxes().forEach(function(checkbox) {
                checkbox.disabled = false;
                checkbox.checked = keys.indexOf(checkbox.dataset.colKey) !== -1;
            });
            state.orderedKeys = keys.slice();
            enforceColumnLimit();
            renderOrderList();
        };

        standardCheckboxes().forEach(function(checkbox) {
            checkbox.addEventListener('change', syncFromCheckboxes);
        });
        addColumnBtn.addEventListener('click', addCustomColumn);
        template.addEventListener('change', function() {
            applyTemplate(template.value);
        });

        applyTemplate(template.value);

        getActivityCohorts().then(function(options) {
            populateSelect(cohortSelect, options.cohorts, function(c) {
                return c.name;
            });
            return makeSearchable(SELECTORS.ACTIVITY_COHORT);
        }).catch(Notification.exception);

        cohortSelect.addEventListener('change', function() {
            var cohortid = parseInt(cohortSelect.value, 10);
            cohortInfo.textContent = '';
            if (!cohortid) {
                return;
            }
            getActivityCohortInfo(cohortid).then(function(info) {
                return Str.getString('activity_cohort_membercount', 'local_profilephoto', info.membercount).then(function(message) {
                    cohortInfo.textContent = message;
                    return null;
                });
            }).catch(Notification.exception);
        });

        var buildColumnsPayload = function() {
            return state.orderedKeys.map(function(key) {
                return {key: key, label: columnLabel(key), type: columnType(key)};
            });
        };

        var collectActivityFields = function() {
            return {
                name: document.querySelector(SELECTORS.ACTIVITY_NAME).value.trim(),
                date: document.querySelector(SELECTORS.ACTIVITY_DATE).value,
                place: document.querySelector(SELECTORS.ACTIVITY_PLACE).value.trim(),
                responsables: document.querySelector(SELECTORS.ACTIVITY_RESPONSABLES).value.trim(),
            };
        };

        var runGeneration = function(onReady) {
            var cohortid = parseInt(cohortSelect.value, 10);
            if (!cohortid) {
                Str.getString('activity_nocohort', 'local_profilephoto').then(function(message) {
                    status.textContent = message;
                    return null;
                }).catch(Notification.exception);
                return;
            }

            previewBtn.disabled = true;
            generateBtn.disabled = true;

            Str.getString('activity_generating', 'local_profilephoto').then(function(message) {
                status.textContent = message;
                return createActivityExport({
                    cohortid: cohortid,
                    activity: collectActivityFields(),
                    columns: buildColumnsPayload(),
                    language: document.querySelector(SELECTORS.ACTIVITY_LANGUAGE).value,
                    stage: document.querySelector(SELECTORS.ACTIVITY_STAGE).value,
                    showphotos: document.querySelector(SELECTORS.ACTIVITY_SHOWPHOTOS).value === '1',
                    showgeneralobs: document.querySelector(SELECTORS.ACTIVITY_SHOWGENERALOBS).checked,
                    order: document.querySelector(SELECTORS.ACTIVITY_ORDER).value,
                    density: document.querySelector(SELECTORS.ACTIVITY_DENSITY).value,
                });
            }).then(function(result) {
                return Str.getString('export_ready', 'local_profilephoto', result.count).then(function(message) {
                    status.textContent = message;
                    var url = M.cfg.wwwroot + '/local/profilephoto/export.php?token=' + result.token;
                    onReady(url);
                    return null;
                });
            }).catch(Notification.exception).finally(function() {
                previewBtn.disabled = false;
                generateBtn.disabled = false;
            });
        };

        generateBtn.addEventListener('click', function() {
            runGeneration(function(url) {
                window.location.href = url;
            });
        });

        previewBtn.addEventListener('click', function() {
            runGeneration(function(url) {
                previewFrame.src = url + (url.indexOf('?') === -1 ? '?' : '&') + 'preview=1';
                previewFrame.hidden = false;
                previewPlaceholder.hidden = true;
            });
        });
    };

    var init = function() {
        initStandardMode();
        initModeToggle();
        if (document.querySelector(SELECTORS.MODE_ACTIVITY)) {
            initActivityMode();
        }
    };

    return {init: init};
});
